export const SOURCES: Record<string, string> = {
  "button": "import type { ComponentProps } from \"react\";\n\n/*\n * basedraft's button: a pill in six materials. Ink for the main action; metal, a charcoal fill\n * inside a brushed edge with a sheen that crosses it on hover, for the one action that matters\n * most on a page; paper, near white under fine dots; glass, for what floats over a picture; outline\n * and ghost for the rest. While it's loading, the label gives way to a field of dots that pulse in\n * an ordered-dither pattern, and the button keeps its width.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nconst VARIANTS = {\n  ink: \"text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.14),0_1px_2px_rgb(var(--bd-shade)/0.2),0_6px_16px_-8px_rgb(var(--bd-shade)/0.5)] hover:brightness-[1.12]\",\n  metal:\n    \"border-[1.5px] border-transparent text-white [background:var(--bd-ui-metal-fill)_padding-box,var(--bd-ui-metal-edge)_border-box] shadow-[inset_0_1px_0_rgb(255_255_255/0.16),0_1px_2px_rgb(0_0_0/0.18),0_8px_20px_-10px_rgb(0_0_0/0.5)] hover:brightness-[1.14]\",\n  paper: \"text-[var(--bd-paper-ink)] [background:var(--bd-ui-paper)] shadow-[var(--bd-ui-lift),inset_0_0_0_1px_rgb(var(--bd-ink)/0.08)] hover:shadow-[var(--bd-ui-lift),inset_0_0_0_1px_rgb(var(--bd-ink)/0.16)]\",\n  glass: \"bg-[color-mix(in_oklab,var(--bd-surface)_60%,transparent)] text-[var(--bd-fg)] backdrop-blur-xl shadow-[inset_0_1px_0_rgb(255_255_255/0.4),inset_0_0_0_1px_rgb(var(--bd-ink)/0.1),0_8px_24px_-12px_rgb(var(--bd-shade)/0.4)] hover:bg-[color-mix(in_oklab,var(--bd-surface)_80%,transparent)]\",\n  outline: \"bg-[var(--bd-surface)] text-[var(--bd-fg)] shadow-[inset_0_0_0_1px_var(--bd-line-strong),0_1px_2px_rgb(var(--bd-shade)/0.06)] hover:bg-[var(--bd-surface-2)]\",\n  ghost: \"text-[var(--bd-muted)] hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\",\n} as const;\n\nconst SIZES = {\n  sm: \"h-8 gap-1.5 px-3.5 text-[13px] [&_svg]:size-3.5\",\n  md: \"h-10 gap-2 px-5 text-sm [&_svg]:size-4\",\n  lg: \"h-12 gap-2.5 px-6 text-[15px] [&_svg]:size-[18px]\",\n  icon: \"size-10 [&_svg]:size-[18px]\",\n} as const;\n\n/* A 4 by 4 ordered-dither matrix: each dot's turn in the pulse, so the field shimmers across rather than blinking at once. */\nconst BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];\nconst COLS = 11;\n\nfunction Dither() {\n  return (\n    <span aria-hidden className=\"absolute inset-0 grid place-items-center\">\n      <span className=\"grid gap-[2.5px]\" style={{ gridTemplateColumns: `repeat(${COLS}, 3px)` }}>\n        {Array.from({ length: COLS * 3 }, (_, i) => {\n          const c = i % COLS;\n          const r = Math.floor(i / COLS);\n          const delay = (c / COLS) * 0.8 + (BAYER[(r % 4) * 4 + (c % 4)] / 16) * 0.45;\n          return <span key={i} className=\"size-[3px] rounded-full bg-current opacity-60 animate-[bd-ui-dither_1.15s_ease-in-out_infinite] motion-reduce:animate-none\" style={{ animationDelay: `${delay.toFixed(3)}s` }} />;\n        })}\n      </span>\n    </span>\n  );\n}\n\nexport type ButtonProps = ComponentProps<\"button\"> & { variant?: keyof typeof VARIANTS; size?: keyof typeof SIZES; loading?: boolean };\n\nexport function Button({ variant = \"ink\", size = \"md\", loading = false, className, type = \"button\", children, disabled, ...props }: ButtonProps) {\n  return (\n    <button\n      type={type}\n      disabled={disabled}\n      aria-busy={loading || undefined}\n      className={cx(\n        \"group/button relative isolate inline-flex shrink-0 select-none items-center justify-center overflow-hidden whitespace-nowrap rounded-full font-medium transition-[background-color,color,filter,scale,box-shadow] duration-200 ease-[var(--bd-ease)] active:scale-[0.97] disabled:pointer-events-none disabled:opacity-45 [&_svg]:shrink-0\",\n        \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[color:var(--bd-ui-focus)]\",\n        VARIANTS[variant],\n        SIZES[size],\n        loading && \"pointer-events-none\",\n        className,\n      )}\n      {...props}\n    >\n      {/* Metal catches the light: a sheen crosses it as the pointer arrives. */}\n      {variant === \"metal\" && <span aria-hidden className=\"pointer-events-none absolute inset-0 -z-10 -translate-x-[110%] bg-[linear-gradient(105deg,transparent_30%,rgb(255_255_255/0.22)_50%,transparent_70%)] transition-transform duration-700 ease-[var(--bd-ease)] group-hover/button:translate-x-[110%] motion-reduce:hidden\" />}\n      <span className={cx(\"inline-flex items-center gap-[inherit] transition-opacity duration-200\", loading && \"opacity-0\")}>{children}</span>\n      {loading && <Dither />}\n    </button>\n  );\n}\n",
  "hold-button": "\"use client\";\n\nimport { CheckIcon } from \"@phosphor-icons/react\";\nimport { animate, AnimatePresence, motion, useMotionValue, useTransform, type AnimationPlaybackControls } from \"motion/react\";\nimport { useEffect, useRef, useState, type ReactNode } from \"react\";\n\n/*\n * For what can't be undone: press and hold, and ink fills the pill from the left as you do. Let go\n * early and it drains away; hold to the end and it confirms, with a check, then comes back after a\n * moment. Space and Enter hold it from the keyboard, the same way.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nconst FILL = {\n  ink: \"text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)]\",\n  stop: \"text-white bg-[var(--bd-ui-stop)]\",\n} as const;\n\nexport type HoldButtonProps = {\n  children: ReactNode;\n  /** What it says once confirmed. */\n  done?: ReactNode;\n  /** How long to hold, in milliseconds. */\n  duration?: number;\n  /** Ink, or red for deleting. */\n  tone?: keyof typeof FILL;\n  icon?: ReactNode;\n  onConfirm?: () => void;\n  className?: string;\n};\n\nexport function HoldButton({ children, done = \"Done\", duration = 1400, tone = \"ink\", icon, onConfirm, className }: HoldButtonProps) {\n  const progress = useMotionValue(0);\n  const clip = useTransform(progress, (v) => `inset(0 ${(1 - v) * 100}% 0 0)`);\n  const [confirmed, setConfirmed] = useState(false);\n  const run = useRef<AnimationPlaybackControls | null>(null);\n\n  const hold = () => {\n    if (confirmed) return;\n    run.current?.stop();\n    run.current = animate(progress, 1, {\n      duration: (duration / 1000) * (1 - progress.get()),\n      ease: \"linear\",\n      onComplete: () => {\n        setConfirmed(true);\n        onConfirm?.();\n      },\n    });\n  };\n  const release = () => {\n    if (confirmed || progress.get() >= 1) return;\n    run.current?.stop();\n    run.current = animate(progress, 0, { type: \"spring\", stiffness: 260, damping: 30 });\n  };\n\n  // Once confirmed, it comes back to rest after a moment, ready again.\n  useEffect(() => {\n    if (!confirmed) return;\n    const t = setTimeout(() => {\n      setConfirmed(false);\n      run.current = animate(progress, 0, { duration: 0.45, ease: [0.16, 1, 0.3, 1] });\n    }, 2200);\n    return () => clearTimeout(t);\n  }, [confirmed, progress]);\n\n  const label = (\n    <>\n      {icon}\n      {children}\n    </>\n  );\n  return (\n    <button\n      type=\"button\"\n      onPointerDown={hold}\n      onPointerUp={release}\n      onPointerLeave={release}\n      onPointerCancel={release}\n      onContextMenu={(e) => e.preventDefault()}\n      onKeyDown={(e) => {\n        if ((e.key === \" \" || e.key === \"Enter\") && !e.repeat) {\n          e.preventDefault();\n          hold();\n        }\n      }}\n      onKeyUp={(e) => {\n        if (e.key === \" \" || e.key === \"Enter\") release();\n      }}\n      className={cx(\n        \"relative isolate inline-flex h-11 shrink-0 touch-none select-none items-center overflow-hidden rounded-full bg-[var(--bd-surface)] text-sm font-medium text-[var(--bd-fg)] shadow-[inset_0_0_0_1px_var(--bd-line-strong),0_1px_2px_rgb(var(--bd-shade)/0.06)] transition-[scale] duration-200 active:scale-[0.98] [&_svg]:size-4 [&_svg]:shrink-0\",\n        \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[color:var(--bd-ui-focus)]\",\n        className,\n      )}\n    >\n      <span className=\"flex items-center gap-2 px-5\">{label}</span>\n      {/* The same label in reverse, on the fill, cut to how far the hold has come. */}\n      <motion.span aria-hidden style={{ clipPath: clip }} className={cx(\"absolute inset-0 flex items-center gap-2 px-5\", FILL[tone])}>\n        {label}\n      </motion.span>\n      <AnimatePresence>\n        {confirmed && (\n          <motion.span initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={cx(\"absolute inset-0 flex items-center justify-center gap-2\", FILL[tone])}>\n            <motion.span initial={{ scale: 0.4, rotate: -30 }} animate={{ scale: 1, rotate: 0 }} transition={{ type: \"spring\", stiffness: 520, damping: 22 }} className=\"grid place-items-center\">\n              <CheckIcon weight=\"bold\" />\n            </motion.span>\n            {done}\n          </motion.span>\n        )}\n      </AnimatePresence>\n      <span className=\"sr-only\" aria-live=\"polite\">\n        {confirmed ? done : \"\"}\n      </span>\n    </button>\n  );\n}\n",
  "copy-button": "\"use client\";\n\nimport { CheckIcon, CopyIcon } from \"@phosphor-icons/react\";\nimport { AnimatePresence, motion } from \"motion/react\";\nimport { useEffect, useState, type ComponentProps } from \"react\";\n\n/*\n * A button that copies a piece of text. Round with just its icon, or a pill that says so; either\n * way the icon turns over into a check, a ring spreads from it, and it settles back after a moment.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\nconst SPRING = { type: \"spring\", stiffness: 600, damping: 30 } as const;\n\nexport type CopyButtonProps = Omit<ComponentProps<\"button\">, \"value\"> & {\n  value: string;\n  /** What a screen reader hears, and what the pill says. */\n  label?: string;\n  variant?: \"icon\" | \"pill\";\n};\n\nexport function CopyButton({ value, label = \"Copy\", variant = \"icon\", className, ...props }: CopyButtonProps) {\n  const [copied, setCopied] = useState(false);\n  useEffect(() => {\n    if (!copied) return;\n    const t = setTimeout(() => setCopied(false), 1600);\n    return () => clearTimeout(t);\n  }, [copied]);\n  const pill = variant === \"pill\";\n  return (\n    <button\n      type=\"button\"\n      aria-label={copied ? \"Copied\" : label}\n      onClick={() => void navigator.clipboard?.writeText(value).then(() => setCopied(true))}\n      className={cx(\n        \"relative inline-flex shrink-0 items-center justify-center rounded-full text-[var(--bd-fg)] transition-[background-color,scale,box-shadow] duration-200 active:scale-[0.94] [background:var(--bd-ui-raised)] shadow-[var(--bd-ui-lift),inset_0_0_0_1px_rgb(var(--bd-ink)/0.07)]\",\n        \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[color:var(--bd-ui-focus)]\",\n        pill ? \"h-8 gap-1.5 pl-2.5 pr-3.5 text-[13px] font-medium\" : \"size-8\",\n        className,\n      )}\n      {...props}\n    >\n      {/* The ring that spreads from a copy. */}\n      <AnimatePresence>\n        {copied && <motion.span key=\"ring\" aria-hidden initial={{ opacity: 0.5, scale: 1 }} animate={{ opacity: 0, scale: 1.6 }} exit={{ opacity: 0 }} transition={{ duration: 0.55, ease: [0.16, 1, 0.3, 1] }} className=\"pointer-events-none absolute inset-0 rounded-full shadow-[0_0_0_1.5px_rgb(var(--bd-ink)/0.35)]\" />}\n      </AnimatePresence>\n      <span className=\"relative grid size-4 place-items-center\">\n        <AnimatePresence mode=\"popLayout\" initial={false}>\n          <motion.span key={copied ? \"done\" : \"copy\"} initial={{ scale: 0.4, opacity: 0, rotate: -40 }} animate={{ scale: 1, opacity: 1, rotate: 0 }} exit={{ scale: 0.4, opacity: 0, rotate: 40 }} transition={SPRING} className=\"grid place-items-center\">\n            {copied ? <CheckIcon size={15} weight=\"bold\" /> : <CopyIcon size={15} weight=\"duotone\" />}\n          </motion.span>\n        </AnimatePresence>\n      </span>\n      {pill && (\n        <AnimatePresence mode=\"popLayout\" initial={false}>\n          <motion.span key={copied ? \"done\" : \"copy\"} initial={{ y: 8, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: -8, opacity: 0 }} transition={SPRING}>\n            {copied ? \"Copied\" : label}\n          </motion.span>\n        </AnimatePresence>\n      )}\n    </button>\n  );\n}\n",
  "command-line": "\"use client\";\n\nimport { CheckIcon, CopyIcon } from \"@phosphor-icons/react\";\nimport { LayoutGroup, motion } from \"motion/react\";\nimport { useEffect, useId, useState } from \"react\";\n\n/*\n * A shell command on a small ink terminal, dark in light mode and dark, colored the way a\n * terminal colors one: the program bright, its arguments gray, flags and addresses in mint, and &&\n * in amber. Give it several commands, keyed by package manager, and it adds a switch between them.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\nconst PROGRAMS = new Set([\"npm\", \"npx\", \"pnpm\", \"pnpx\", \"bun\", \"bunx\", \"yarn\", \"cd\", \"git\", \"claude\", \"curl\", \"unzip\"]);\n\n/** Splits a command into words, each with its color; a program only counts as the first word of its command. */\nfunction tokens(command: string) {\n  let first = true;\n  return command.split(/(\\s+)/).map((p) => {\n    if (/^\\s+$/.test(p)) return { p, tone: \"\" };\n    let tone = \"text-[oklch(78%_0_0)]\";\n    if (p === \"&&\" || p === \"|\" || p === \";\") {\n      tone = \"text-[oklch(80%_0.12_75)]\";\n      first = true;\n    } else if (first && PROGRAMS.has(p)) {\n      tone = \"font-medium text-white\";\n      first = false;\n    } else if (/^-{1,2}\\w/.test(p) || /^https?:\\/\\//.test(p) || /^[\"']/.test(p)) tone = \"text-[oklch(84%_0.09_165)]\";\n    else first = false;\n    return { p, tone };\n  });\n}\n\nexport function CommandLine({ command, commands, label, className }: { command?: string; commands?: Record<string, string>; /** A word on what it's for, beside the switch. */ label?: string; className?: string }) {\n  const keys = commands ? Object.keys(commands) : [];\n  const [at, setAt] = useState(keys[0] ?? \"\");\n  const [copied, setCopied] = useState(false);\n  const id = useId();\n  const text = commands ? commands[at] : (command ?? \"\");\n  useEffect(() => {\n    if (!copied) return;\n    const t = setTimeout(() => setCopied(false), 1600);\n    return () => clearTimeout(t);\n  }, [copied]);\n  return (\n    <div className={cx(\"overflow-hidden rounded-[18px] text-sm text-[oklch(92%_0_0)] [background:linear-gradient(180deg,oklch(25%_0.004_265),oklch(17%_0.004_265))] shadow-[inset_0_1px_0_rgb(255_255_255/0.08),inset_0_0_0_1px_rgb(255_255_255/0.06),0_14px_32px_-16px_rgb(var(--bd-shade)/0.6)]\", className)}>\n      {(keys.length > 1 || label) && (\n        <div className=\"flex items-center gap-2 px-2 pt-2\">\n          {/* Three quiet dots, so it reads as a terminal at a glance. */}\n          <span aria-hidden className=\"flex gap-1 px-2\">\n            <span className=\"size-2 rounded-full bg-white/15\" />\n            <span className=\"size-2 rounded-full bg-white/15\" />\n            <span className=\"size-2 rounded-full bg-white/15\" />\n          </span>\n          {label && <span className=\"truncate text-xs text-white/45\">{label}</span>}\n          {keys.length > 1 && (\n            <LayoutGroup id={id}>\n              <div role=\"tablist\" aria-label=\"Package manager\" className=\"ml-auto flex gap-0.5 rounded-full bg-white/[0.05] p-0.5\">\n                {keys.map((k) => (\n                  <button key={k} type=\"button\" role=\"tab\" aria-selected={k === at} onClick={() => setAt(k)} className={cx(\"relative h-6 rounded-full px-2.5 font-mono text-[11.5px] transition-colors focus-visible:outline-2 focus-visible:outline-white/40\", k === at ? \"text-white\" : \"text-white/50 hover:text-white/80\")}>\n                    {k === at && <motion.span layoutId=\"manager\" className=\"absolute inset-0 rounded-full bg-white/[0.13] shadow-[inset_0_1px_0_rgb(255_255_255/0.08)]\" transition={{ type: \"spring\", stiffness: 520, damping: 42 }} />}\n                    <span className=\"relative\">{k}</span>\n                  </button>\n                ))}\n              </div>\n            </LayoutGroup>\n          )}\n        </div>\n      )}\n      <div className=\"flex items-center gap-2 py-2 pl-4 pr-2\">\n        <code className=\"min-w-0 flex-1 overflow-x-auto whitespace-nowrap py-1 font-mono text-[13px] [scrollbar-width:none]\">\n          <span className=\"select-none text-white/35\">$ </span>\n          {tokens(text).map(({ p, tone }, i) =>\n            tone ? (\n              <span key={i} className={tone}>\n                {p}\n              </span>\n            ) : (\n              p\n            ),\n          )}\n        </code>\n        <button type=\"button\" aria-label={copied ? \"Copied\" : \"Copy the command\"} onClick={() => void navigator.clipboard?.writeText(text).then(() => setCopied(true))} className=\"grid size-8 shrink-0 place-items-center rounded-full bg-white/[0.06] text-white/70 transition-[background-color,color,scale] hover:bg-white/[0.12] hover:text-white active:scale-[0.94] focus-visible:outline-2 focus-visible:outline-white/40\">\n          {copied ? <CheckIcon size={14} weight=\"bold\" className=\"text-[oklch(84%_0.09_165)]\" /> : <CopyIcon size={14} weight=\"duotone\" />}\n        </button>\n      </div>\n    </div>\n  );\n}\n",
  "input": "import type { ComponentProps, ReactNode } from \"react\";\n\n/*\n * A text field as a pill pressed into the page: a soft well while it waits, lifting to a white\n * face with an ink edge when you type in it. Something can lead it (an icon) or trail it (a\n * suffix, a hint), and they stay quiet beside the text.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nexport type InputProps = ComponentProps<\"input\"> & { leading?: ReactNode; trailing?: ReactNode };\n\nexport function Input({ leading, trailing, className, type = \"text\", ...props }: InputProps) {\n  return (\n    <span\n      className={cx(\n        \"flex h-11 w-full items-center gap-2.5 rounded-full bg-[var(--bd-surface-2)] px-4 text-sm text-[var(--bd-fg)] shadow-[var(--bd-ui-well)] transition-[background-color,box-shadow] duration-200 ease-[var(--bd-ease)]\",\n        \"hover:bg-[color-mix(in_oklab,var(--bd-surface-2)_60%,var(--bd-surface))] focus-within:bg-[var(--bd-surface)] focus-within:shadow-[inset_0_0_0_1px_rgb(var(--bd-ink)/0.4),0_0_0_4px_rgb(var(--bd-ink)/0.06)]\",\n        \"has-[[aria-invalid=true]]:shadow-[inset_0_0_0_1px_var(--bd-ui-stop),0_0_0_4px_color-mix(in_oklab,var(--bd-ui-stop)_14%,transparent)] has-[:disabled]:opacity-50\",\n        className,\n      )}\n    >\n      {leading && <span className=\"flex shrink-0 text-[var(--bd-subtle)] [&_svg]:size-4\">{leading}</span>}\n      <input type={type} className=\"h-full min-w-0 flex-1 bg-transparent outline-none placeholder:text-[var(--bd-subtle)] disabled:cursor-not-allowed\" {...props} />\n      {trailing && <span className=\"flex shrink-0 items-center text-[13px] text-[var(--bd-subtle)] [&_svg]:size-4\">{trailing}</span>}\n    </span>\n  );\n}\n",
  "textarea": "\"use client\";\n\nimport { useState, type ComponentProps } from \"react\";\n\n/*\n * A longer field that grows with what's typed into it, pressed into the page like the input. Give\n * it a limit and it counts as you type, on a small ring that fills, turning amber near the end\n * and red past it.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nexport type TextareaProps = ComponentProps<\"textarea\"> & { showCount?: boolean };\n\nexport function Textarea({ className, maxLength, showCount = false, value, defaultValue, onChange, ...props }: TextareaProps) {\n  const [typed, setTyped] = useState(String(defaultValue ?? \"\").length);\n  const count = value !== undefined ? String(value).length : typed;\n  const counting = showCount && !!maxLength;\n  const share = counting ? Math.min(1, count / maxLength) : 0;\n  const tone = share >= 1 ? \"var(--bd-ui-stop)\" : share > 0.85 ? \"var(--bd-ui-wait)\" : \"var(--bd-fg)\";\n  return (\n    <span\n      className={cx(\n        \"flex w-full flex-col rounded-[20px] bg-[var(--bd-surface-2)] text-sm text-[var(--bd-fg)] shadow-[var(--bd-ui-well)] transition-[background-color,box-shadow] duration-200 ease-[var(--bd-ease)]\",\n        \"focus-within:bg-[var(--bd-surface)] focus-within:shadow-[inset_0_0_0_1px_rgb(var(--bd-ink)/0.4),0_0_0_4px_rgb(var(--bd-ink)/0.06)] has-[:disabled]:opacity-50\",\n        className,\n      )}\n    >\n      <textarea\n        value={value}\n        defaultValue={defaultValue}\n        maxLength={maxLength}\n        onChange={(e) => {\n          setTyped(e.target.value.length);\n          onChange?.(e);\n        }}\n        className=\"max-h-[240px] min-h-[96px] w-full resize-none bg-transparent px-4 pb-2 pt-3.5 leading-relaxed outline-none [field-sizing:content] placeholder:text-[var(--bd-subtle)]\"\n        {...props}\n      />\n      {counting && (\n        <span className=\"flex items-center justify-end gap-2 px-4 pb-3 text-[11px] tabular-nums text-[var(--bd-subtle)]\">\n          {count} of {maxLength}\n          <svg viewBox=\"0 0 16 16\" className=\"size-3.5 -rotate-90\" aria-hidden>\n            <circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"rgb(var(--bd-ink) / 0.12)\" strokeWidth=\"2\" />\n            <circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke={tone} strokeWidth=\"2\" strokeLinecap=\"round\" strokeDasharray={`${share * 37.7} 37.7`} className=\"transition-[stroke-dasharray,stroke] duration-300\" />\n          </svg>\n        </span>\n      )}\n    </span>\n  );\n}\n",
  "switch": "\"use client\";\n\nimport { motion } from \"motion/react\";\nimport { useState, type ComponentProps } from \"react\";\n\n/*\n * An on and off switch: a track pressed into the page, filling with ink when it's on, and a bead\n * for a knob that stretches while you press it and springs across when you let go.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nconst SIZES = {\n  sm: { track: \"h-5 w-[34px]\", knob: 14, stretch: 4 },\n  md: { track: \"h-[26px] w-11\", knob: 20, stretch: 5 },\n} as const;\n\nexport type SwitchProps = Omit<ComponentProps<\"button\">, \"onChange\"> & { checked?: boolean; defaultChecked?: boolean; onCheckedChange?: (checked: boolean) => void; size?: keyof typeof SIZES };\n\nexport function Switch({ checked, defaultChecked = false, onCheckedChange, size = \"md\", className, disabled, ...props }: SwitchProps) {\n  const [inner, setInner] = useState(defaultChecked);\n  const [pressed, setPressed] = useState(false);\n  const on = checked ?? inner;\n  const s = SIZES[size];\n  return (\n    <button\n      type=\"button\"\n      role=\"switch\"\n      aria-checked={on}\n      disabled={disabled}\n      onClick={() => {\n        setInner(!on);\n        onCheckedChange?.(!on);\n      }}\n      onPointerDown={() => setPressed(true)}\n      onPointerUp={() => setPressed(false)}\n      onPointerLeave={() => setPressed(false)}\n      className={cx(\n        \"relative inline-flex shrink-0 items-center rounded-full p-[3px] shadow-[var(--bd-ui-well)] transition-[background-color] duration-300 disabled:cursor-not-allowed disabled:opacity-45\",\n        \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[color:var(--bd-ui-focus)]\",\n        on ? \"justify-end [background:var(--bd-ui-ink)]\" : \"justify-start bg-[var(--bd-surface-2)]\",\n        s.track,\n        className,\n      )}\n      {...props}\n    >\n      <motion.span\n        layout=\"position\"\n        animate={{ width: pressed ? s.knob + s.stretch : s.knob }}\n        transition={{ type: \"spring\", stiffness: 640, damping: 34 }}\n        className={cx(\"block rounded-full shadow-[0_1px_1px_rgb(var(--bd-shade)/0.2),0_2px_6px_-1px_rgb(var(--bd-shade)/0.28),inset_0_-1px_0_rgb(var(--bd-ink)/0.06)]\", on ? \"[background:var(--bd-ui-bead-on)]\" : \"[background:var(--bd-ui-bead)]\")}\n        style={{ height: s.knob, width: s.knob }}\n      />\n    </button>\n  );\n}\n",
  "segmented": "\"use client\";\n\nimport { LayoutGroup, motion } from \"motion/react\";\nimport { useId, useRef, useState, type KeyboardEvent, type ReactNode } from \"react\";\n\n/*\n * One choice of a few, in a track machined into the page, the chosen one on a raised thumb that\n * slides to the next. The arrow keys move the choice, as they do in any radio group.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nexport type SegmentedOption = { value: string; label: ReactNode; icon?: ReactNode };\n\nexport function Segmented({ options, value, defaultValue, onValueChange, label, size = \"md\", className }: { options: SegmentedOption[]; value?: string; defaultValue?: string; onValueChange?: (value: string) => void; label: string; size?: \"sm\" | \"md\"; className?: string }) {\n  const [inner, setInner] = useState(defaultValue ?? options[0]?.value);\n  const id = useId();\n  const track = useRef<HTMLDivElement>(null);\n  const current = value ?? inner;\n  const pick = (v: string) => {\n    setInner(v);\n    onValueChange?.(v);\n  };\n  const onKey = (e: KeyboardEvent) => {\n    const step = e.key === \"ArrowRight\" || e.key === \"ArrowDown\" ? 1 : e.key === \"ArrowLeft\" || e.key === \"ArrowUp\" ? -1 : 0;\n    if (!step) return;\n    e.preventDefault();\n    const i = options.findIndex((o) => o.value === current);\n    const next = options[(i + step + options.length) % options.length];\n    pick(next.value);\n    track.current?.querySelector<HTMLElement>(`[data-value=\"${CSS.escape(next.value)}\"]`)?.focus();\n  };\n  return (\n    <LayoutGroup id={id}>\n      <div ref={track} role=\"radiogroup\" aria-label={label} onKeyDown={onKey} className={cx(\"inline-flex w-fit items-center gap-0.5 rounded-full bg-[var(--bd-surface-2)] p-1 shadow-[var(--bd-ui-well)]\", className)}>\n        {options.map((o) => {\n          const on = o.value === current;\n          return (\n            <button\n              key={o.value}\n              type=\"button\"\n              role=\"radio\"\n              aria-checked={on}\n              tabIndex={on ? 0 : -1}\n              data-value={o.value}\n              onClick={() => pick(o.value)}\n              className={cx(\n                \"relative flex flex-1 items-center justify-center gap-1.5 whitespace-nowrap rounded-full font-medium transition-colors duration-200\",\n                \"focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[color:var(--bd-ui-focus)]\",\n                size === \"sm\" ? \"h-7 px-3 text-[12.5px] [&_svg]:size-3.5\" : \"h-9 px-4 text-sm [&_svg]:size-4\",\n                on ? \"text-[var(--bd-fg)]\" : \"text-[var(--bd-subtle)] hover:text-[var(--bd-fg)]\",\n              )}\n            >\n              {on && <motion.span layoutId=\"thumb\" className=\"absolute inset-0 rounded-full [background:var(--bd-ui-raised)] shadow-[var(--bd-ui-lift),inset_0_0_0_1px_rgb(var(--bd-ink)/0.06)]\" transition={{ type: \"spring\", stiffness: 520, damping: 40 }} />}\n              {o.icon && <span className=\"relative flex\">{o.icon}</span>}\n              <span className=\"relative\">{o.label}</span>\n            </button>\n          );\n        })}\n      </div>\n    </LayoutGroup>\n  );\n}\n",
  "slider": "\"use client\";\n\nimport { AnimatePresence, motion } from \"motion/react\";\nimport { useId, useState } from \"react\";\n\n/*\n * A value along a track: ink fills it up to a bead you drag, a small ink bubble over the bead says\n * the value while you hold or focus it, and marks under the track show the stops that matter. A\n * real range input sits over it all, so dragging, the arrow keys and screen readers work as usual.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\nconst THUMB = 22;\n\nexport type SliderProps = {\n  min?: number;\n  max?: number;\n  step?: number;\n  value?: number;\n  defaultValue?: number;\n  onValueChange?: (value: number) => void;\n  /** Its name, shown above it with the value. */\n  label?: string;\n  /** How a value reads: \"96 px\", \"40%\". */\n  format?: (value: number) => string;\n  /** Values to mark under the track, each with its number. */\n  ticks?: number[];\n  disabled?: boolean;\n  className?: string;\n};\n\nexport function Slider({ min = 0, max = 100, step = 1, value, defaultValue, onValueChange, label, format = String, ticks, disabled, className }: SliderProps) {\n  const [inner, setInner] = useState(defaultValue ?? min);\n  const [held, setHeld] = useState(false);\n  const [focused, setFocused] = useState(false);\n  const id = useId();\n  const v = value ?? inner;\n  const share = (v - min) / (max - min);\n  // The bead's center runs from half a bead in at either end, so it never leaves the track.\n  const at = (s: number) => `calc(${s * 100}% + ${(0.5 - s) * THUMB}px)`;\n  return (\n    <div className={cx(\"w-full\", disabled && \"opacity-45\", className)}>\n      {label && (\n        <div className=\"mb-3 flex items-baseline justify-between gap-4 text-sm\">\n          <label htmlFor={id} className=\"font-medium text-[var(--bd-fg)]\">\n            {label}\n          </label>\n          <span className=\"tabular-nums text-[var(--bd-muted)]\">{format(v)}</span>\n        </div>\n      )}\n      <div className=\"relative h-7\">\n        <input\n          id={id}\n          type=\"range\"\n          min={min}\n          max={max}\n          step={step}\n          value={v}\n          disabled={disabled}\n          aria-valuetext={format(v)}\n          onChange={(e) => {\n            const n = Number(e.target.value);\n            setInner(n);\n            onValueChange?.(n);\n          }}\n          onPointerDown={() => setHeld(true)}\n          onPointerUp={() => setHeld(false)}\n          // The bubble stays up for the keyboard; for a pointer it shows only while held.\n          onFocus={(e) => setFocused(e.currentTarget.matches(\":focus-visible\"))}\n          onBlur={() => {\n            setFocused(false);\n            setHeld(false);\n          }}\n          className=\"peer absolute inset-0 z-10 h-full w-full cursor-pointer opacity-0 disabled:cursor-not-allowed\"\n        />\n        <span className=\"absolute inset-x-0 top-1/2 h-2 -translate-y-1/2 rounded-full bg-[var(--bd-surface-2)] shadow-[var(--bd-ui-well)]\" />\n        <span className=\"absolute left-0 top-1/2 h-2 -translate-y-1/2 rounded-full [background:var(--bd-ui-ink)]\" style={{ width: at(share) }} />\n        <span\n          className=\"absolute top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full [background:var(--bd-ui-bead)] shadow-[0_1px_1px_rgb(var(--bd-shade)/0.2),0_3px_8px_-2px_rgb(var(--bd-shade)/0.3),inset_0_0_0_1px_rgb(var(--bd-ink)/0.08)] transition-[scale] duration-200 peer-active:scale-110 peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-[color:var(--bd-ui-focus)]\"\n          style={{ left: at(share), width: THUMB, height: THUMB }}\n        >\n          <AnimatePresence>\n            {(held || focused) && (\n              <motion.span\n                initial={{ opacity: 0, y: 4, scale: 0.9 }}\n                animate={{ opacity: 1, y: 0, scale: 1 }}\n                exit={{ opacity: 0, y: 4, scale: 0.9 }}\n                transition={{ type: \"spring\", stiffness: 600, damping: 32 }}\n                className=\"pointer-events-none absolute bottom-full left-1/2 mb-2.5 -translate-x-1/2 whitespace-nowrap rounded-[8px] px-2 py-1 text-[11.5px] font-medium tabular-nums text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[var(--bd-shadow-float)]\"\n              >\n                {format(v)}\n                <span aria-hidden className=\"absolute left-1/2 top-full size-2 -translate-x-1/2 -translate-y-1 rotate-45 rounded-[1px] bg-[var(--bd-ui-ink-solid)]\" />\n              </motion.span>\n            )}\n          </AnimatePresence>\n        </span>\n      </div>\n      {ticks && ticks.length > 0 && (\n        <div className=\"relative mt-1 h-6\">\n          {ticks.map((t) => {\n            const s = (t - min) / (max - min);\n            return (\n              <span key={t} className=\"absolute top-0 flex -translate-x-1/2 flex-col items-center gap-1\" style={{ left: at(s) }}>\n                <span className={cx(\"h-1.5 w-px rounded-full\", t <= v ? \"bg-[var(--bd-fg)]\" : \"bg-[var(--bd-line-strong)]\")} />\n                <span className=\"text-[10.5px] tabular-nums text-[var(--bd-subtle)]\">{t}</span>\n              </span>\n            );\n          })}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "tabs": "\"use client\";\n\nimport { AnimatePresence, LayoutGroup, motion } from \"motion/react\";\nimport { createContext, use, useId, useState, type ComponentProps, type KeyboardEvent, type ReactNode } from \"react\";\n\n/*\n * Tabs as a quiet row of names, the selected one inked on a pill that slides to the next, and its\n * panel rising in under them. The arrow keys move between tabs. Controlled with value and\n * onValueChange, or left to keep its own state.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\ntype TabsState = { value: string; setValue: (v: string) => void; id: string };\nconst TabsContext = createContext<TabsState | null>(null);\nconst useTabs = () => {\n  const ctx = use(TabsContext);\n  if (!ctx) throw new Error(\"Tabs parts go inside <Tabs>.\");\n  return ctx;\n};\n\nexport function Tabs({ value, defaultValue = \"\", onValueChange, className, children }: { value?: string; defaultValue?: string; onValueChange?: (value: string) => void; className?: string; children: ReactNode }) {\n  const [inner, setInner] = useState(defaultValue);\n  const id = useId();\n  const current = value ?? inner;\n  const setValue = (v: string) => {\n    setInner(v);\n    onValueChange?.(v);\n  };\n  return (\n    <TabsContext value={{ value: current, setValue, id }}>\n      <LayoutGroup id={id}>\n        <div className={cx(\"flex flex-col gap-4\", className)}>{children}</div>\n      </LayoutGroup>\n    </TabsContext>\n  );\n}\n\nexport function TabsList({ className, onKeyDown, ...props }: ComponentProps<\"div\">) {\n  const tabs = useTabs();\n  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {\n    onKeyDown?.(e);\n    const step = e.key === \"ArrowRight\" ? 1 : e.key === \"ArrowLeft\" ? -1 : 0;\n    if (!step) return;\n    e.preventDefault();\n    const all = [...e.currentTarget.querySelectorAll<HTMLButtonElement>(\"[role=tab]\")];\n    const i = all.findIndex((b) => b.getAttribute(\"aria-selected\") === \"true\");\n    const next = all[(i + step + all.length) % all.length];\n    next?.focus();\n    if (next?.dataset.value) tabs.setValue(next.dataset.value);\n  };\n  return <div role=\"tablist\" onKeyDown={onKey} className={cx(\"inline-flex w-fit items-center gap-1 rounded-full p-1 shadow-[inset_0_0_0_1px_var(--bd-line)]\", className)} {...props} />;\n}\n\nexport function TabsTrigger({ value, className, children, ...props }: ComponentProps<\"button\"> & { value: string }) {\n  const tabs = useTabs();\n  const on = tabs.value === value;\n  return (\n    <button\n      type=\"button\"\n      role=\"tab\"\n      id={`${tabs.id}-tab-${value}`}\n      data-value={value}\n      aria-selected={on}\n      aria-controls={`${tabs.id}-panel-${value}`}\n      tabIndex={on ? 0 : -1}\n      onClick={() => tabs.setValue(value)}\n      className={cx(\n        \"relative flex h-8 items-center gap-1.5 rounded-full px-4 text-sm font-medium transition-colors duration-200 [&_svg]:size-4\",\n        \"focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[color:var(--bd-ui-focus)]\",\n        on ? \"text-[var(--bd-ui-ink-text)]\" : \"text-[var(--bd-muted)] hover:text-[var(--bd-fg)]\",\n        className,\n      )}\n      {...props}\n    >\n      {on && <motion.span layoutId=\"tab\" className=\"absolute inset-0 rounded-full [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.14),0_4px_12px_-6px_rgb(var(--bd-shade)/0.5)]\" transition={{ type: \"spring\", stiffness: 520, damping: 42 }} />}\n      <span className=\"relative flex items-center gap-1.5\">{children}</span>\n    </button>\n  );\n}\n\nexport function TabsContent({ value, className, children }: { value: string; className?: string; children: ReactNode }) {\n  const tabs = useTabs();\n  return (\n    <AnimatePresence mode=\"wait\" initial={false}>\n      {tabs.value === value && (\n        <motion.div\n          key={value}\n          role=\"tabpanel\"\n          id={`${tabs.id}-panel-${value}`}\n          aria-labelledby={`${tabs.id}-tab-${value}`}\n          initial={{ opacity: 0, y: 8, filter: \"blur(3px)\" }}\n          animate={{ opacity: 1, y: 0, filter: \"blur(0px)\" }}\n          exit={{ opacity: 0, y: -4, filter: \"blur(2px)\" }}\n          transition={{ duration: 0.24, ease: [0.16, 1, 0.3, 1] }}\n          className={className}\n        >\n          {children}\n        </motion.div>\n      )}\n    </AnimatePresence>\n  );\n}\n",
  "accordion": "\"use client\";\n\nimport { PlusIcon } from \"@phosphor-icons/react\";\nimport { AnimatePresence, motion } from \"motion/react\";\nimport { Children, createContext, use, useId, useState, type ReactNode } from \"react\";\n\n/*\n * Questions in a numbered list on one card: each row has its number, the question, and a plus\n * that turns into a cross as its answer springs open to its own height. One open at a time, or\n * several with type=\"multiple\".\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\ntype AccordionState = { open: string[]; toggle: (v: string) => void; numbered: boolean };\nconst AccordionContext = createContext<AccordionState | null>(null);\nconst ItemContext = createContext<{ value: string; id: string; n: number } | null>(null);\nconst NumberContext = createContext(0);\n\nexport function Accordion({ type = \"single\", defaultValue = [], numbered = true, className, children }: { type?: \"single\" | \"multiple\"; defaultValue?: string[]; /** A number before each question. */ numbered?: boolean; className?: string; children: ReactNode }) {\n  const [open, setOpen] = useState<string[]>(defaultValue);\n  const toggle = (v: string) => setOpen((o) => (o.includes(v) ? o.filter((x) => x !== v) : type === \"single\" ? [v] : [...o, v]));\n  return (\n    <AccordionContext value={{ open, toggle, numbered }}>\n      <div className={cx(\"overflow-hidden rounded-[20px] bg-[var(--bd-surface)] shadow-[inset_0_0_0_1px_var(--bd-line),var(--bd-shadow-resting)]\", className)}>\n        {/* Each item learns its place in the list, for its number. */}\n        {Children.toArray(children).map((child, i) => (\n          <NumberContext key={i} value={i + 1}>\n            {child}\n          </NumberContext>\n        ))}\n      </div>\n    </AccordionContext>\n  );\n}\n\nexport function AccordionItem({ value, className, children }: { value: string; className?: string; children: ReactNode }) {\n  const id = useId();\n  const n = use(NumberContext);\n  const acc = use(AccordionContext)!;\n  const on = acc.open.includes(value);\n  return (\n    <ItemContext value={{ value, id, n }}>\n      <div className={cx(\"border-t border-[var(--bd-line-subtle)] transition-colors duration-300 first:border-t-0\", on && \"bg-[var(--bd-surface-2)]\", className)}>{children}</div>\n    </ItemContext>\n  );\n}\n\nexport function AccordionTrigger({ className, children }: { className?: string; children: ReactNode }) {\n  const acc = use(AccordionContext)!;\n  const item = use(ItemContext)!;\n  const on = acc.open.includes(item.value);\n  return (\n    <button\n      type=\"button\"\n      id={`${item.id}-trigger`}\n      aria-expanded={on}\n      aria-controls={`${item.id}-content`}\n      onClick={() => acc.toggle(item.value)}\n      className={cx(\"flex w-full items-center gap-3.5 px-4 py-3.5 text-left text-sm font-medium text-[var(--bd-fg)] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[color:var(--bd-ui-focus)]\", className)}\n    >\n      {acc.numbered && <span className={cx(\"w-5 shrink-0 font-mono text-[11px] tabular-nums transition-colors duration-300\", on ? \"text-[var(--bd-fg)]\" : \"text-[var(--bd-subtle)]\")}>{String(item.n).padStart(2, \"0\")}</span>}\n      <span className=\"min-w-0 flex-1\">{children}</span>\n      <span className={cx(\"grid size-6 shrink-0 place-items-center rounded-full transition-[rotate,background-color,color] duration-300 ease-[var(--bd-ease)]\", on ? \"rotate-45 text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)]\" : \"bg-[var(--bd-surface-2)] text-[var(--bd-muted)] shadow-[var(--bd-ui-well)]\")}>\n        <PlusIcon size={12} weight=\"regular\" />\n      </span>\n    </button>\n  );\n}\n\nexport function AccordionContent({ className, children }: { className?: string; children: ReactNode }) {\n  const acc = use(AccordionContext)!;\n  const item = use(ItemContext)!;\n  const on = acc.open.includes(item.value);\n  return (\n    <AnimatePresence initial={false}>\n      {on && (\n        <motion.div\n          id={`${item.id}-content`}\n          role=\"region\"\n          aria-labelledby={`${item.id}-trigger`}\n          initial={{ height: 0, opacity: 0 }}\n          animate={{ height: \"auto\", opacity: 1 }}\n          exit={{ height: 0, opacity: 0 }}\n          transition={{ height: { type: \"spring\", stiffness: 380, damping: 38 }, opacity: { duration: 0.2 } }}\n          className=\"overflow-hidden\"\n        >\n          <div className={cx(\"pb-4 pr-12 text-sm leading-relaxed text-[var(--bd-muted)]\", acc.numbered ? \"pl-[50px]\" : \"pl-4\", className)}>{children}</div>\n        </motion.div>\n      )}\n    </AnimatePresence>\n  );\n}\n",
  "badge": "import type { ComponentProps } from \"react\";\n\n/*\n * A small stamp beside a name: inked, quiet, outlined, on paper, or rimmed in metal. It can lead\n * with a status dot (ready, waiting, stopped or idle), and a live one pulses.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nconst VARIANTS = {\n  default: \"text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.14)]\",\n  secondary: \"bg-[var(--bd-surface-2)] text-[var(--bd-muted)] shadow-[inset_0_0_0_1px_rgb(var(--bd-ink)/0.06)]\",\n  outline: \"bg-[var(--bd-surface)] text-[var(--bd-fg)] shadow-[inset_0_0_0_1px_var(--bd-line-strong)]\",\n  paper: \"text-[var(--bd-paper-ink)] [background:var(--bd-ui-paper)] shadow-[inset_0_0_0_1px_rgb(var(--bd-ink)/0.1),0_1px_2px_rgb(var(--bd-shade)/0.06)]\",\n  metal: \"border-[1.5px] border-transparent text-white [background:var(--bd-ui-metal-fill)_padding-box,var(--bd-ui-metal-edge)_border-box] shadow-[0_1px_2px_rgb(0_0_0/0.18)]\",\n} as const;\n\nconst DOTS = { ok: \"bg-[var(--bd-ui-ok)]\", wait: \"bg-[var(--bd-ui-wait)]\", stop: \"bg-[var(--bd-ui-stop)]\", idle: \"bg-[var(--bd-subtle)]\" } as const;\n\nexport type BadgeProps = ComponentProps<\"span\"> & { variant?: keyof typeof VARIANTS; dot?: keyof typeof DOTS; live?: boolean };\n\nexport function Badge({ variant = \"default\", dot, live = false, className, children, ...props }: BadgeProps) {\n  return (\n    <span className={cx(\"inline-flex h-6 shrink-0 items-center gap-1.5 whitespace-nowrap rounded-full px-2.5 text-[11.5px] font-medium leading-none tracking-[0.005em] [&_svg]:size-3\", VARIANTS[variant], className)} {...props}>\n      {dot && (\n        <span aria-hidden className=\"relative grid size-1.5 place-items-center\">\n          {live && <span className={cx(\"absolute inset-0 rounded-full animate-[bd-ui-pulse_1.6s_ease-out_infinite] motion-reduce:hidden\", DOTS[dot])} />}\n          <span className={cx(\"relative size-1.5 rounded-full\", DOTS[dot])} />\n        </span>\n      )}\n      {children}\n    </span>\n  );\n}\n",
  "card": "import type { ComponentProps } from \"react\";\n\n/*\n * A card and its parts: a head with a title and a line under it, the content, and a foot for\n * actions. It sits on a plain surface or on paper (near white, with fine dots), and can wear a\n * brushed-metal edge for the one card on a page that matters most.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nconst FACES = {\n  surface: \"bg-[var(--bd-surface)] text-[var(--bd-fg)]\",\n  paper: \"text-[var(--bd-paper-ink)] [background:var(--bd-ui-paper)]\",\n} as const;\n\nexport type CardProps = ComponentProps<\"div\"> & { variant?: keyof typeof FACES; edge?: boolean };\n\nexport function Card({ variant = \"surface\", edge = false, className, children, ...props }: CardProps) {\n  if (edge)\n    return (\n      <div className={cx(\"rounded-[22px] p-[1.5px] [background:var(--bd-ui-metal-edge)] shadow-[0_1px_2px_rgb(var(--bd-shade)/0.08),0_18px_40px_-20px_rgb(var(--bd-shade)/0.45)]\", className)} {...props}>\n        <div className={cx(\"overflow-hidden rounded-[20.5px]\", FACES[variant])}>{children}</div>\n      </div>\n    );\n  return (\n    <div className={cx(\"overflow-hidden rounded-[20px] shadow-[inset_0_0_0_1px_var(--bd-line),0_1px_2px_rgb(var(--bd-shade)/0.05),0_14px_32px_-18px_rgb(var(--bd-shade)/0.35)]\", FACES[variant], className)} {...props}>\n      {children}\n    </div>\n  );\n}\n\nexport function CardHeader({ className, ...props }: ComponentProps<\"div\">) {\n  return <div className={cx(\"flex flex-col gap-1 p-5 pb-0\", className)} {...props} />;\n}\n\nexport function CardTitle({ className, ...props }: ComponentProps<\"h3\">) {\n  return <h3 className={cx(\"text-[15px] font-semibold leading-tight tracking-[-0.01em]\", className)} {...props} />;\n}\n\nexport function CardDescription({ className, ...props }: ComponentProps<\"p\">) {\n  return <p className={cx(\"text-[13px] text-[var(--bd-muted)]\", className)} {...props} />;\n}\n\nexport function CardContent({ className, ...props }: ComponentProps<\"div\">) {\n  return <div className={cx(\"p-5\", className)} {...props} />;\n}\n\nexport function CardFooter({ className, ...props }: ComponentProps<\"div\">) {\n  return <div className={cx(\"flex items-center gap-2 border-t border-[rgb(var(--bd-ink)/0.07)] bg-[rgb(var(--bd-ink)/0.02)] px-5 py-3\", className)} {...props} />;\n}\n",
  "avatar": "\"use client\";\n\nimport { useState, type ComponentProps } from \"react\";\n\n/*\n * A person's picture, or their initials on a soft stone tint drawn from their name, so the same\n * person always looks the same. A dot in the corner says whether they're here, busy or away. In a\n * group they overlap, with a count for the rest, and fan out when you point at them.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nconst SIZES = { sm: \"size-7 text-[10px]\", md: \"size-9 text-xs\", lg: \"size-12 text-sm\" } as const;\nconst DOT = { sm: \"size-2\", md: \"size-2.5\", lg: \"size-3\" } as const;\nconst STATUS = { online: \"bg-[var(--bd-ui-ok)]\", busy: \"bg-[var(--bd-ui-stop)]\", away: \"bg-[var(--bd-ui-wait)]\" } as const;\n/* How far each one in a group tucks under the one before, and how far apart they fan when pointed at. */\nconst STACK = {\n  sm: \"[&>*+*]:-ml-2 hover:[&>*+*]:ml-0.5\",\n  md: \"[&>*+*]:-ml-2 hover:[&>*+*]:ml-1\",\n  lg: \"[&>*+*]:-ml-3.5 hover:[&>*+*]:ml-1\",\n} as const;\n\nexport type AvatarProps = ComponentProps<\"span\"> & { src?: string; name: string; size?: keyof typeof SIZES; status?: keyof typeof STATUS };\n\n/** A hue from 0 to 359 for a name, the same every time. */\nconst hue = (name: string) => [...name].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 360, 7);\n\nexport function Avatar({ src, name, size = \"md\", status, className, ...props }: AvatarProps) {\n  const [failed, setFailed] = useState(false);\n  const initials = name\n    .split(/\\s+/)\n    .filter(Boolean)\n    .slice(0, 2)\n    .map((w) => w[0]!.toUpperCase())\n    .join(\"\");\n  const h = hue(name);\n  return (\n    <span className={cx(\"relative inline-flex shrink-0\", SIZES[size], className)} title={name} {...props}>\n      <span\n        className=\"grid size-full place-items-center overflow-hidden rounded-full font-semibold tracking-[0.02em] shadow-[inset_0_1px_0_rgb(255_255_255/0.5),inset_0_0_0_1px_rgb(0_0_0/0.06)]\"\n        style={{ backgroundImage: `linear-gradient(150deg, oklch(0.94 0.022 ${h}), oklch(0.82 0.035 ${h + 40}))`, color: `oklch(0.34 0.03 ${h})` }}\n      >\n        {src && !failed ? (\n          // eslint-disable-next-line @next/next/no-img-element\n          <img src={src} alt={name} onError={() => setFailed(true)} className=\"size-full object-cover\" />\n        ) : (\n          <span role=\"img\" aria-label={name}>\n            {initials}\n          </span>\n        )}\n      </span>\n      {status && <span role=\"img\" aria-label={status} className={cx(\"absolute bottom-0 right-0 rounded-full ring-2 ring-[var(--bd-surface)]\", DOT[size], STATUS[status])} />}\n    </span>\n  );\n}\n\nexport function AvatarGroup({ people, max = 4, size = \"md\", className }: { people: Array<{ name: string; src?: string; status?: keyof typeof STATUS }>; max?: number; size?: keyof typeof SIZES; className?: string }) {\n  const shown = people.slice(0, max);\n  const rest = people.length - shown.length;\n  return (\n    <span className={cx(\"flex items-center [&>*]:transition-[margin] [&>*]:duration-300 [&>*]:ease-[var(--bd-ease)]\", STACK[size], className)}>\n      {shown.map((p) => (\n        <Avatar key={p.name} {...p} size={size} className=\"rounded-full ring-2 ring-[var(--bd-surface)]\" />\n      ))}\n      {rest > 0 && (\n        <span className={cx(\"relative inline-grid shrink-0 place-items-center rounded-full bg-[var(--bd-surface-2)] font-semibold text-[var(--bd-muted)] shadow-[var(--bd-ui-well)] ring-2 ring-[var(--bd-surface)]\", SIZES[size])} title={people.slice(max).map((p) => p.name).join(\", \")}>\n          +{rest}\n        </span>\n      )}\n    </span>\n  );\n}\n",
  "kbd": "\"use client\";\n\nimport { useEffect, useState, type ComponentProps } from \"react\";\n\n/*\n * A keyboard key drawn as a real keycap, a raised face on a darker edge. It listens for its own\n * key: press that key on your keyboard (or click the cap) and it goes down, the way the key under\n * your finger does. Write the key as you'd see it on a Mac: ⌘, ⇧, ⌥, ⌃, ↵, or a letter.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\n/* The symbol on a cap, as the key the browser reports. */\nconst KEYS: Record<string, string> = { \"⌘\": \"Meta\", \"⇧\": \"Shift\", \"⌥\": \"Alt\", \"⌃\": \"Control\", \"↵\": \"Enter\", \"⌫\": \"Backspace\", Esc: \"Escape\", Tab: \"Tab\", Space: \" \", \"←\": \"ArrowLeft\", \"→\": \"ArrowRight\", \"↑\": \"ArrowUp\", \"↓\": \"ArrowDown\" };\n\nconst SIZES = {\n  sm: \"h-5 min-w-5 rounded-[5px] px-1 text-[10.5px]\",\n  md: \"h-7 min-w-7 rounded-[7px] px-1.5 text-xs\",\n} as const;\n\nexport type KbdProps = ComponentProps<\"kbd\"> & { size?: keyof typeof SIZES; /** Go down when this key is pressed on the keyboard. */ listen?: boolean };\n\nexport function Kbd({ size = \"md\", listen = true, className, children, ...props }: KbdProps) {\n  const label = typeof children === \"string\" ? children : \"\";\n  const key = KEYS[label] ?? label;\n  const [down, setDown] = useState(false);\n  useEffect(() => {\n    if (!listen || !key) return;\n    const match = (e: KeyboardEvent) => (key.length === 1 ? e.key.toLowerCase() === key.toLowerCase() : e.key === key);\n    const press = (e: KeyboardEvent) => match(e) && setDown(true);\n    // On a Mac, keys let go while ⌘ is held never say so; letting go of ⌘ lets go of them all.\n    const lift = (e: KeyboardEvent) => (match(e) || e.key === \"Meta\") && setDown(false);\n    const reset = () => setDown(false);\n    window.addEventListener(\"keydown\", press);\n    window.addEventListener(\"keyup\", lift);\n    window.addEventListener(\"blur\", reset);\n    return () => {\n      window.removeEventListener(\"keydown\", press);\n      window.removeEventListener(\"keyup\", lift);\n      window.removeEventListener(\"blur\", reset);\n    };\n  }, [listen, key]);\n  return (\n    <kbd\n      onPointerDown={() => setDown(true)}\n      onPointerUp={() => setDown(false)}\n      onPointerLeave={() => setDown(false)}\n      className={cx(\n        \"inline-flex select-none items-center justify-center font-sans font-medium text-[var(--bd-fg)] [background:var(--bd-ui-raised)] transition-[translate,box-shadow] duration-100 ease-out\",\n        down\n          ? \"translate-y-[1.5px] shadow-[inset_0_1px_0_rgb(255_255_255/0.4),inset_0_0_0_1px_rgb(var(--bd-ink)/0.12),0_0.5px_0_rgb(var(--bd-ink)/0.2)]\"\n          : \"shadow-[inset_0_1px_0_rgb(255_255_255/0.7),inset_0_0_0_1px_rgb(var(--bd-ink)/0.1),0_2px_0_rgb(var(--bd-ink)/0.16),0_3px_6px_-2px_rgb(var(--bd-shade)/0.22)]\",\n        SIZES[size],\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </kbd>\n  );\n}\n\nexport function KbdGroup({ className, ...props }: ComponentProps<\"span\">) {\n  return <span className={cx(\"inline-flex items-center gap-1\", className)} {...props} />;\n}\n",
  "tooltip": "\"use client\";\n\nimport { AnimatePresence, motion } from \"motion/react\";\nimport { useId, useRef, useState, type ReactNode } from \"react\";\n\n/*\n * A short label in an ink bubble with a caret, rising in over what it describes on hover or\n * keyboard focus after a moment's pause. It can carry the keys for the action too, on small caps.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\nexport function Tooltip({ content, keys, side = \"top\", delay = 160, className, children }: { content: ReactNode; /** Its shortcut, a cap each: [\"⌘\", \"E\"]. */ keys?: string[]; side?: \"top\" | \"bottom\"; delay?: number; className?: string; children: ReactNode }) {\n  const [open, setOpen] = useState(false);\n  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);\n  const id = useId();\n  const show = () => {\n    clearTimeout(timer.current);\n    timer.current = setTimeout(() => setOpen(true), delay);\n  };\n  const hide = () => {\n    clearTimeout(timer.current);\n    setOpen(false);\n  };\n  const top = side === \"top\";\n  return (\n    <span className=\"relative inline-flex\" onPointerEnter={show} onPointerLeave={hide} onFocus={show} onBlur={hide} aria-describedby={open ? id : undefined}>\n      {children}\n      <AnimatePresence>\n        {open && (\n          <motion.span\n            id={id}\n            role=\"tooltip\"\n            initial={{ opacity: 0, y: top ? 6 : -6, scale: 0.94 }}\n            animate={{ opacity: 1, y: 0, scale: 1 }}\n            exit={{ opacity: 0, scale: 0.97, transition: { duration: 0.1 } }}\n            transition={{ type: \"spring\", stiffness: 620, damping: 34 }}\n            className={cx(\n              \"pointer-events-none absolute left-1/2 z-50 flex -translate-x-1/2 items-center gap-2 whitespace-nowrap rounded-[10px] py-1.5 pl-2.5 text-xs font-medium text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.12),var(--bd-shadow-float)]\",\n              keys?.length ? \"pr-1.5\" : \"pr-2.5\",\n              top ? \"bottom-full mb-2.5 origin-bottom\" : \"top-full mt-2.5 origin-top\",\n              className,\n            )}\n          >\n            {content}\n            {keys && keys.length > 0 && (\n              <span className=\"flex gap-0.5\">\n                {keys.map((k) => (\n                  <kbd key={k} className=\"grid h-[18px] min-w-[18px] place-items-center rounded-[5px] bg-[color-mix(in_oklab,var(--bd-ui-ink-text)_16%,transparent)] px-1 font-sans text-[10.5px] font-medium\">\n                    {k}\n                  </kbd>\n                ))}\n              </span>\n            )}\n            {/* The caret, pointing at what it describes. */}\n            <span aria-hidden className={cx(\"absolute left-1/2 size-2 -translate-x-1/2 rotate-45 rounded-[1.5px] bg-[var(--bd-ui-ink-solid)]\", top ? \"top-full -translate-y-[5px]\" : \"bottom-full translate-y-[5px]\")} />\n          </motion.span>\n        )}\n      </AnimatePresence>\n    </span>\n  );\n}\n",
  "meter": "\"use client\";\n\nimport { useMotionValueEvent, useSpring } from \"motion/react\";\nimport { useEffect, useState } from \"react\";\n\n/*\n * How far along something is, drawn in dots: ink dots up to the value, faint ones after it, and\n * between them an edge that dissolves through an ordered dither, the way a printed gradient does.\n * When the value changes, the edge springs to it.\n */\n\nconst cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(\" \");\n\n/* A 4 by 4 ordered-dither matrix: where each dot falls in the edge between filled and empty. */\nconst BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];\n\nexport type MeterProps = {\n  value: number;\n  max?: number;\n  /** What it measures, shown above it. */\n  label?: string;\n  /** The value as it reads, beside the label. A percent by default. */\n  valueLabel?: string;\n  /** How many dots across and down. */\n  cols?: number;\n  rows?: number;\n  className?: string;\n};\n\nexport function Meter({ value, max = 100, label, valueLabel, cols = 40, rows = 4, className }: MeterProps) {\n  const target = Math.max(0, Math.min(1, value / max));\n  const spring = useSpring(target, { stiffness: 90, damping: 22 });\n  const [p, setP] = useState(target);\n  useEffect(() => {\n    spring.set(target);\n  }, [spring, target]);\n  useMotionValueEvent(spring, \"change\", setP);\n  // How many columns the dithered edge spreads across.\n  const spread = 7 / cols;\n  return (\n    <div role=\"meter\" aria-valuemin={0} aria-valuemax={max} aria-valuenow={value} aria-valuetext={valueLabel} aria-label={label} className={cx(\"w-full\", className)}>\n      {(label || valueLabel) && (\n        <div className=\"mb-2.5 flex items-baseline justify-between gap-4 text-sm\">\n          <span className=\"font-medium text-[var(--bd-fg)]\">{label}</span>\n          <span className=\"tabular-nums text-[var(--bd-muted)]\">{valueLabel ?? `${Math.round(target * 100)}%`}</span>\n        </div>\n      )}\n      <div aria-hidden className=\"grid gap-[3px]\" style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}>\n        {Array.from({ length: cols * rows }, (_, i) => {\n          const c = i % cols;\n          const r = Math.floor(i / cols);\n          const x = (c + 0.5) / cols;\n          const threshold = (BAYER[(r % 4) * 4 + (c % 4)] + 0.5) / 16;\n          // Filled well behind the value, empty well past it, and dithered across the edge between.\n          const on = x + (threshold - 0.5) * spread < p * (1 + spread) - spread / 2;\n          return <span key={i} className={cx(\"aspect-square rounded-full transition-colors duration-150\", on ? \"bg-[rgb(var(--bd-ink)/0.85)]\" : \"bg-[rgb(var(--bd-ink)/0.1)]\")} />;\n        })}\n      </div>\n    </div>\n  );\n}\n"
};
